-- Athena saved query (Product_B2C_Intl)
-- ID: 7aa3cc6a-8282-4d59-ba04-b02f1e662e62
-- Name: users search for return trip RTR AB - non Pilgrim - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), (205655),(94782),(300439) ) AS x(dest_id) ), /* ------------------------------------------------------------ 1. Base successful bookings for pilgrims -------------------------------------------------------------*/ base_users AS ( SELECT DISTINCT __time AS basedate, rb_user_id, src_id AS base_src_id, dest_id AS base_dest_id FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2025-11-01 00:00:00' AND __time < TIMESTAMP '2025-11-15 00:00:00' AND status_str = 'SUCCESS' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND tin IS NOT NULL AND dest_id NOT IN (SELECT dest_id FROM piligrim_dest_list) ), /* ------------------------------------------------------------ 2. All post-booking searches for these users (OPTIMIZED) We filter and calculate rtr_variant in the subquery (s) to reduce data volume before the join. -------------------------------------------------------------*/ all_post_search AS ( SELECT b.rb_user_id, b.base_src_id, b.base_dest_id, b.basedate, s.search_src_id, s.search_dest_id, s.searchdate, s.rtr_variant FROM base_users b LEFT JOIN ( SELECT rb_user_id, __time AS searchdate, src_id AS search_src_id, dest_id AS search_dest_id, CASE WHEN contains(channel_exp_info, 'RTR_SRP_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'RTR_SRP_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'RTR_SRP_AB:V2') THEN 'V2' ELSE NULL END AS rtr_variant FROM user_interaction.search_details WHERE __time >= TIMESTAMP '2025-11-01 00:00:00' AND __time < TIMESTAMP '2025-12-01 00:00:00' AND os = 'Android' AND country = 'IND' ) s -- Join condition: s.__time > b.basedate is handled implicitly below due to date ranges. -- However, we must explicitly ensure the search happened after the base booking. ON s.rb_user_id = b.rb_user_id AND s.searchdate > b.basedate ), /* ------------------------------------------------------------ 3. All confirmed bookings in Nov 2025 (for return matching) -------------------------------------------------------------*/ return_confirm AS ( SELECT DISTINCT rb_user_id, src_id, dest_id FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2025-11-01 00:00:00' AND __time < TIMESTAMP '2025-12-01 00:00:00' AND status_str = 'SUCCESS' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' ) SELECT a.rtr_variant, -- Grouping by the experiment variant /* Base Users (Note: this is the count of unique users who made the base booking and then made a search where rtr_variant was V0, V1, or V2) */ COUNT(DISTINCT b.rb_user_id) AS base_users, /* A: Any search */ COUNT(DISTINCT CASE WHEN a.searchdate IS NOT NULL THEN a.rb_user_id END) AS any_sd_searched_users, /* B: exact return route search (D→S) */ COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND a.search_dest_id = a.base_src_id THEN a.rb_user_id END ) AS return_route_searched_users, /* C: D → pilgrim destination X (X ≠ base_src_id) */ COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND pd1.dest_id = a.search_dest_id AND a.search_dest_id <> a.base_src_id THEN a.rb_user_id END ) AS piligrim_searched_users, /* D: D → non-pilgrim */ COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND pd1.dest_id IS NULL THEN a.rb_user_id END ) AS different_dest_searched_users, /* E: neither src nor dest in pilgrim list */ COUNT(DISTINCT CASE WHEN pd2.dest_id IS NULL AND pd1.dest_id IS NULL THEN a.rb_user_id END ) AS other_sd_searched_users, /* --- Confirmed versions --- */ COUNT(DISTINCT CASE WHEN rc.rb_user_id IS NOT NULL THEN a.rb_user_id END) AS any_sd_confirmed_users, COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND a.search_dest_id = a.base_src_id AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS return_route_confirmed_users, COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND pd1.dest_id = a.search_dest_id AND a.search_dest_id <> a.base_src_id AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS piligrim_confirmed_users, COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND pd1.dest_id IS NULL AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS different_dest_confirmed_users, COUNT(DISTINCT CASE WHEN pd2.dest_id IS NULL AND pd1.dest_id IS NULL AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS other_sd_confirmed_users FROM all_post_search a JOIN base_users b ON a.rb_user_id = b.rb_user_id LEFT JOIN return_confirm rc ON a.rb_user_id = rc.rb_user_id AND a.search_src_id = rc.src_id AND a.search_dest_id = rc.dest_id /* Pre-joined pilgrim lists for speed */ LEFT JOIN piligrim_dest_list pd1 ON a.search_dest_id = pd1.dest_id LEFT JOIN piligrim_dest_list pd2 ON a.search_src_id = pd2.dest_id GROUP BY 1 ORDER BY 1;
